import{_ as r,o,c as n,a3 as s}from"./chunks/framework.bvEHUNtb.js";const p=JSON.parse('{"title":"象数易理篇之三：八卦类象与万物属类","description":"建立八卦与天时、地理、人物、器物等万物之间的取象词典。","frontmatter":{"title":"象数易理篇之三：八卦类象与万物属类","description":"建立八卦与天时、地理、人物、器物等万物之间的取象词典。","category":"学习计划 · 第一阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md","filePath":"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md","lastUpdated":1786982540000}'),g={name:"yijing/meihua-yishu/xiang-shu-li/trigram-correspondence.md"};function a(d,t,b,e,i,l){return o(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="【象数易理篇之三】八卦类象与万物属类" tabindex="-1">【象数易理篇之三】八卦类象与万物属类 <a class="header-anchor" href="#【象数易理篇之三】八卦类象与万物属类" aria-label="Permalink to &quot;【象数易理篇之三】八卦类象与万物属类&quot;">​</a></h1><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="八卦类象" tabindex="-1">八卦类象 <a class="header-anchor" href="#八卦类象" aria-label="Permalink to &quot;八卦类象&quot;">​</a></h3><p><strong>乾</strong>：玄黄、大赤色、金玉、宝珠、镜、狮、圆物、木果、贵物、冠、象、马、天鹅、刚物。</p><p><strong>坎</strong>：水、带子带核之物、豕鱼、弓轮、水具、水中之屋、盐、酒、黑色。</p><p><strong>艮</strong>：土石、黄色、虎、狗、土中之物、瓜果、百禽、鼠、黔喙之属。</p><p><strong>震</strong>：竹木、青碧绿色、龙、蛇、苇、竹木乐器、草、蕃鲜之物。</p><p><strong>巽</strong>：木、蛇、长物、青碧绿色、山木之禽鸟、香、鸡、直物、竹木之器、工巧之器。</p><p><strong>离</strong>：火、文书、干戈、雉、龟、蟹、槁木、甲胄、螺、蚌、鳖、赤色。</p><p><strong>坤</strong>：土、方物、五谷、柔物、丝绵、百禽、牛、布帛、舆、金、瓦器、黄色。</p><p><strong>兑</strong>：金刃、金器、乐器、泽中之物、白色、有口缺之物、羊。</p><hr><h3 id="八卦万物属类" tabindex="-1">八卦万物属类 <a class="header-anchor" href="#八卦万物属类" aria-label="Permalink to &quot;八卦万物属类&quot;">​</a></h3><h4 id="☰-乾卦-一-金" tabindex="-1">☰ 乾卦　一　金 <a class="header-anchor" href="#☰-乾卦-一-金" aria-label="Permalink to &quot;☰ 乾卦　一　金&quot;">​</a></h4><p>乾为天　天风姤　天山遁　天地否<br> 风地观　山地剥　火地晋　火天大有</p><p><strong>天时</strong>：天、冰、雹、霰。<br><strong>地理</strong>：西北方、京都、大郡、形胜之地、高亢之所。<br><strong>人物</strong>：君、父、大人、老人、长者、官宦、名人、公门人。<br><strong>人事</strong>：刚健武勇、果决、多动少静、高上下屈。<br><strong>身体</strong>：首、骨、肺。<br><strong>时序</strong>：秋、九十月之交、戌亥年月日时、一四九年月日时。<br><strong>动物</strong>：马、天鹅、狮、象。<br><strong>静物</strong>：金玉、宝珠、圆物、水果、刚物、冠、镜。<br><strong>屋舍</strong>：公廨、楼台、高堂、大厦、驿舍、西北向之居。<br><strong>家宅</strong>：秋占宅兴隆、夏占有祸、冬占冷落、春占吉利。<br><strong>婚姻</strong>：贵官之眷、有声名之家、秋占宜成、冬夏占不利。<br><strong>饮食</strong>：马肉、珍味、多骨、肝肺、干肉、水果、诸物之首、圆物、辛辣之物。<br><strong>生产</strong>：易生、秋占生贵子，夏占有损，坐宜向西北。<br><strong>求名</strong>：有名、宜随朝内任、刑官、武职、掌权、天使、驿官、宜西北方之任。<br><strong>谋旺</strong>：有成、利公门、宜动中有财、夏占不成、冬占多谋少遂。<br><strong>交易</strong>：宜金、玉珍宝珠贵货、易成、夏占不利。<br><strong>求利</strong>：有财、金、玉之利、公门中得财、秋占大利、夏占损财、冬占无财。<br><strong>出行</strong>：利于出行、宜入京师、利西北之行、夏占不利。<br><strong>谒见</strong>：利见大人、有德行之人、宜见官贵、可见。<br><strong>疾病</strong>：头面之疾、肺疾、筋骨疾、上焦疾、夏占不安。<br><strong>官讼</strong>：健讼、有贵人助、秋占得胜、夏占失理。<br><strong>坟墓</strong>：宜向西北、宜干山气脉、宜天穴、宜高、秋占出贵、夏占大凶。<br><strong>方道</strong>：西北。<br><strong>五色</strong>：大赤色、玄色。<br><strong>姓字</strong>：带金旁者、商音、行位一四九。<br><strong>数目</strong>：一、四、九。<br><strong>五味</strong>：辛、辣。</p><hr><h4 id="☷-坤卦-八-土" tabindex="-1">☷ 坤卦　八　土 <a class="header-anchor" href="#☷-坤卦-八-土" aria-label="Permalink to &quot;☷ 坤卦　八　土&quot;">​</a></h4><p>坤为地　地雷复　地泽临　地天泰<br> 雷天大壮　泽天决　水天需　水地比</p><p><strong>天时</strong>：云阴、雾气。<br><strong>地理</strong>：田野、乡里、平地、西南方。<br><strong>人物</strong>：老母、后母、农夫、乡人、众人、大腹人。<br><strong>人事</strong>：吝啬、柔顺、懦弱、众多。<br><strong>身体</strong>：腹、脾、胃、肉。<br><strong>时序</strong>：辰戌丑未月、未申年月日时、八五十月日。<br><strong>静物</strong>：方物、柔物、布帛、丝绵、五谷、舆釜、瓦器。<br><strong>动物</strong>：牛、百兽、牝马。<br><strong>屋舍</strong>：西南向、村居、田舍、矮屋、土阶、仓库。<br><strong>家宅</strong>：安稳、多阴气、春占宅舍不安。<br><strong>饮食</strong>：牛肉、土中之物、甘味、野味、五谷之味、芋笋之物、腹脏之物。<br><strong>婚姻</strong>：利于婚姻、宜税产之家、乡村之家、或寡妇之家、春占不利。<br><strong>生产</strong>：易产、春占难产、有损、或不利于母、坐宜西南方。<br><strong>求名</strong>：有名、宜西南方或教官、农官守土之职、春占虚名。<br><strong>交易</strong>：宜利交易、宜田土交易、宜五谷、利贱货、重物、布帛、静中有财、春占不利。<br><strong>求利</strong>：有利、宜土中之利、贱货重物之利、静中得财、春占无财、多中取利。<br><strong>谋旺</strong>：利求谋、乡里求谋、静中求谋、春占少遂、或谋于妇人。<br><strong>出行</strong>：可行、宜西南行、宜往乡里行、宜陆行、春占不宜行。<br><strong>谒见</strong>：可见、利见乡人、宜见亲朋或阴人、春不宜见。<br><strong>疾病</strong>：腹疾、脾胃之疾、饮食停伤、谷食不化。<br><strong>官讼</strong>：理顺、得众情、讼当解散。<br><strong>坟墓</strong>：宜向西南之穴、平阳之地、近田野、宜低葬、春不可葬。<br><strong>姓字</strong>：宫音、带土姓人、行位八五十。<br><strong>数目</strong>：八、五、十。<br><strong>方道</strong>：西南。<br><strong>五味</strong>：甘。<br><strong>五色</strong>：黄、黑。</p><hr><h4 id="☳-震卦-四-木" tabindex="-1">☳ 震卦　四　木 <a class="header-anchor" href="#☳-震卦-四-木" aria-label="Permalink to &quot;☳ 震卦　四　木&quot;">​</a></h4><p>震为雷　雷地豫　雷水解　雷风恒<br> 地风升　水风井　泽风大过　泽雷随</p><p><strong>天时</strong>：雷。<br><strong>地理</strong>：东方、树木、闹市、大途、竹林、草木茂盛之所。<br><strong>人物</strong>：长男。<br><strong>人事</strong>：起动、怒、虚惊、鼓动噪、多动少静。<br><strong>身体</strong>：足、肝、发、声音。<br><strong>时序</strong>：春三月、卯年月日时、四三八月日。<br><strong>静物</strong>：木竹、萑苇、乐器（属竹木者）、花草繁鲜之物。<br><strong>动物</strong>：龙、蛇。<br><strong>屋舍</strong>：东向之居、山林之处、楼阁。<br><strong>家宅</strong>：宅中不时有虚惊、春冬吉、秋占不利。<br><strong>饮食</strong>：蹄、肉、山林野味、鲜肉、果酸味、菜蔬。<br><strong>婚姻</strong>：可、有成、声名之家、得长男之婚、秋占不宜婚。<br><strong>求利</strong>：山林竹木之财、动处求财、或山林、竹木茶货之利。<br><strong>求名</strong>：有名、宜东方之任、施号发令之职、掌刑狱之官、竹茶木税课之任、或闹市司货之职。<br><strong>生产</strong>：虚惊、胎动不安、头胎必生男、坐宜东向、秋占必有损。<br><strong>疾病</strong>：足疾、肝经之疾、惊怖不安。<br><strong>谋旺</strong>：可旺、可求、宜动中谋、秋占不遂。<br><strong>交易</strong>：利于成交、秋占难成、动而可成、山林、木竹茶货之利。<br><strong>官讼</strong>：健讼、有虚惊、行移取甚反复。<br><strong>谒见</strong>：可见、在山林之人、利见宜有声名之人。<br><strong>出行</strong>：宜行、利于东方、利山林之人、秋占不宜行、但恐虚惊。<br><strong>坟墓</strong>：利于东向、山林中穴、秋不利。<br><strong>姓字</strong>：角音、带木姓人、行位四八三。<br><strong>数目</strong>：四、八、三。<br><strong>方道</strong>：东。<br><strong>五味</strong>：甘、酸味。<br><strong>五色</strong>：青、绿、碧。</p><hr><h4 id="☴-巽卦-五-木" tabindex="-1">☴ 巽卦　五　木 <a class="header-anchor" href="#☴-巽卦-五-木" aria-label="Permalink to &quot;☴ 巽卦　五　木&quot;">​</a></h4><p>巽为风　风天小畜　风火家人　风雷益<br> 天雷无妄　火雷噬嗑　山雷颐　山风蛊</p><p><strong>天时</strong>：风。<br><strong>地理</strong>：东南方之地、草木茂秀之所、花果菜园。<br><strong>人物</strong>：长女、秀士、寡妇之人、山林仙道之人。<br><strong>人事</strong>：柔和、不定、鼓舞、利市三倍、进退不果。<br><strong>身体</strong>：肱、股、气、风疾。<br><strong>时序</strong>：春夏之交、三五八之时月日、辰巳月日时。<br><strong>静物</strong>：木香、绳、直物、长物、竹木、工巧之器。<br><strong>动物</strong>：鸡、百禽、山林中之禽、虫。<br><strong>屋舍</strong>：东南向之居、寺观楼台、山林之居。<br><strong>家宅</strong>：安稳利市、春占吉、秋占不安。<br><strong>饮食</strong>：鸡肉、山林之味、蔬果酸味。<br><strong>婚姻</strong>：可成、宜长女之婚、秋占不利。<br><strong>生产</strong>：易生、头胎产女、秋占损胎、宜向东南坐。<br><strong>求名</strong>：有名、宜文职有风宪之力、宜为风宪、宜茶果竹木税货之职、宜东南之任。<br><strong>求利</strong>：有利三倍、宜山林之利、秋占不利、竹货木货之利。<br><strong>交易</strong>：可成、进退不一、利山林交易、山林木茶之利。<br><strong>谋旺</strong>：可谋旺、有财可成、秋占多谋少遂。<br><strong>出行</strong>：可行、有出入之利、宜向东南行、秋占不利。<br><strong>谒见</strong>：可见、利见山林之人、利见文人秀士。<br><strong>疾病</strong>：股肱之疾、风疾、肠疾、中风、寒邪、气疾。<br><strong>姓字</strong>：角音、草木旁姓氏、行位五三八。<br><strong>官讼</strong>：宜和、恐遭风宪之责。<br><strong>坟墓</strong>：宜东南方向、山林之穴、多树木、秋占不利。<br><strong>数目</strong>：五、三、八。<br><strong>方道</strong>：东南。<br><strong>五味</strong>：酸味。<br><strong>五色</strong>：青、绿、碧、洁白。</p><hr><h4 id="☵-坎卦-六-水" tabindex="-1">☵ 坎卦　六　水 <a class="header-anchor" href="#☵-坎卦-六-水" aria-label="Permalink to &quot;☵ 坎卦　六　水&quot;">​</a></h4><p>坎为水　水泽节　水雷屯　水火既济<br> 泽火革　雷火丰　地火明夷　地水师</p><p><strong>天时</strong>：月、雨、雪、霜、露。<br><strong>地理</strong>：北方、江湖、溪涧、泉井、卑湿之地（沟渎、池沼、凡有水处）。<br><strong>人物</strong>：中男、江湖之人、舟人、资贼。<br><strong>人事</strong>：险陷卑下、外示以柔、内序以利、漂泊不成、随波逐流。<br><strong>身体</strong>：耳、血、肾。<br><strong>时序</strong>：冬十一月、子年月日时、一六月日。<br><strong>静物</strong>：水带子、带核之物、弓轮、矫揉之物、酒器、水具。<br><strong>屋舍</strong>：向北之居、近水、水阁、江楼、花酒长器、宅中混地之处。<br><strong>饮食</strong>：豕肉、酒、冷味、海味、汤、酸味、宿食、鱼、带血、掩藏、有带核之物、水中之物、多骨之物。<br><strong>家宅</strong>：不安、暗昧、防盗。<br><strong>婚姻</strong>：利中男之婚、宜北方之婚、辰戌丑未月婚不可。<br><strong>生产</strong>：难产有险、宜次胎、中男、辰戌丑未月有损、宜北向。<br><strong>求名</strong>：艰难、恐有灾险、宜北方之任、鱼盐河泊之职。<br><strong>求利</strong>：有财失、宜水边财、恐有失陷、宜鱼盐酒货之利、防遗失、防盗。<br><strong>交易</strong>：不利成交、恐防失陷、宜水边交易、宜鱼盐货之交易、或点水人之交易。<br><strong>谋旺</strong>：不宜谋旺、不能成就、秋冬占可谋旺。<br><strong>出行</strong>：不宜远行、宜涉舟、宜北方之行、防盗、恐遇险陷溺之事。<br><strong>谒见</strong>：难见、宜见江湖之人、或有水旁姓氏之人。<br><strong>疾病</strong>：耳痛、心疾、感寒、肾疾、胃冷、水泻、痼冷之病、血病。<br><strong>官讼</strong>：不利、有阴险、有失、因讼、失陷。<br><strong>坟墓</strong>：宜北向之穴、近水傍之墓、不利葬。<br><strong>姓字</strong>：羽音、点水旁之姓氏、行位一六。<br><strong>数目</strong>：一、六。<br><strong>方道</strong>：北方。<br><strong>五味</strong>：咸、酸。<br><strong>五色</strong>：黑。</p><hr><h4 id="☲-离卦-三-火" tabindex="-1">☲ 离卦　三　火 <a class="header-anchor" href="#☲-离卦-三-火" aria-label="Permalink to &quot;☲ 离卦　三　火&quot;">​</a></h4><p>离为火　火山旅　火风鼎　火水未济<br> 山水蒙　风水涣　天水讼　天火同人</p><p><strong>天时</strong>：日、电、虹、霓、霞。<br><strong>地理</strong>：南方、干亢之地、窖灶、炉冶之所、刚燥厥地、其地面阳。<br><strong>人物</strong>：中女、文人、大腹、目疾人、甲胄之士。<br><strong>人事</strong>：文画之所、聪明才学、相见虚心、书事。<br><strong>身体</strong>：目、心、上焦。<br><strong>时序</strong>：夏五月、午火年月日时、三二七日。<br><strong>静物</strong>：火、书、文、甲胄、干戈、槁衣、干燥之物、赤色之物。<br><strong>动物</strong>：雉、龟、鳖、蟹、螺、蚌。<br><strong>屋舍</strong>：南舍之居、阳明之宅、明窗、虚室。<br><strong>家宅</strong>：安稳、平善、冬占不安、克体主火灾。<br><strong>饮食</strong>：雉肉、煎炒、烧炙之物、干脯之体、热肉。<br><strong>婚姻</strong>：不成、利中女之婚、夏占可成、冬占不利。<br><strong>生产</strong>：易生、产中女、冬占有损、坐宜向南。<br><strong>求名</strong>：有名、宜南方之职、文官之任、宜炉冶亢场之职。<br><strong>求利</strong>：有财宜南方求、有文书之财、冬占有失。<br><strong>谋旺</strong>：可以谋旺、宜文书之事。<br><strong>交易</strong>：可成、宜有文书之交易。<br><strong>出行</strong>：可行、宜向南方、就文书之行、冬占不宜行、不宜行舟。<br><strong>谒见</strong>：可见南方人、冬占不顺、秋见文书考案之士。<br><strong>官讼</strong>：易散、文书动、辞讼明辨。<br><strong>疾病</strong>：目疾、心疾、上焦热病、夏占伏暑、时疫。<br><strong>坟墓</strong>：南向之幕、无树木之所、阳穴。夏占出文人、冬占不利。<br><strong>姓字</strong>：征音、立人旁士姓氏、行位三二七。<br><strong>数目</strong>：三、二、七。<br><strong>方道</strong>：南。<br><strong>五色</strong>：赤、紫、红。<br><strong>五味</strong>：苦。</p><hr><h4 id="☶-艮卦-七-土" tabindex="-1">☶ 艮卦　七　土 <a class="header-anchor" href="#☶-艮卦-七-土" aria-label="Permalink to &quot;☶ 艮卦　七　土&quot;">​</a></h4><p>艮为山　山火贲　山天大畜　山泽损<br> 火泽睽　天泽履　风泽中孚　风山渐</p><p><strong>天时</strong>：云、雾、山岚。<br><strong>地理</strong>：山径路、近山城、丘陵、坟墓、东北方。<br><strong>人物</strong>：少男、闲人、山中人。<br><strong>人事</strong>：阻隔、守静、进退不决、反背、止住、不见。<br><strong>身体</strong>：手指、骨、鼻、背。<br><strong>时序</strong>：冬春之月、十二月丑寅年月日时、七五十数月日、土年月日时。<br><strong>静物</strong>：土石、瓜果、黄物、土中之物。<br><strong>动物</strong>：虎、狗、鼠、百兽、黔啄之物。<br><strong>家宅</strong>：安稳、诸事有阻、家人不睦、春占不安。<br><strong>屋舍</strong>：东北方之居、山居近石、近路之宅。<br><strong>饮食</strong>：土中物味、诸兽之肉、墓畔竹笋之属、野味。<br><strong>婚姻</strong>：阻隔难成、成亦迟、利少男之婚、春占不利、宜对乡里婚。<br><strong>求名</strong>：阻隔无名、宜东北方之任、宜土官山城之职。<br><strong>求利</strong>：求财阻隔、宜山林中取财、春占不利、有损失。<br><strong>生产</strong>：难生、有险阻之厄、宜向东北、春占有损。<br><strong>交易</strong>：难成、有山林田土之交易、春占有失。<br><strong>谋旺</strong>：阻隔难成、进退不决。<br><strong>出行</strong>：不宜远行、有阻、宜近陆行。<br><strong>谒见</strong>：不可见、有阻、宜见山林之人。<br><strong>疾病</strong>：手指之疾、脾胃之疾。<br><strong>官讼</strong>：贵人阻滞、官讼未解、牵连不决。<br><strong>坟墓</strong>：东北之穴、山中之穴、春占不利、近路旁有石。<br><strong>数目</strong>：五、七、十。<br><strong>方道</strong>：东北方。<br><strong>五色</strong>：黄。<br><strong>五味</strong>：甘。</p><hr><h4 id="☱-兑卦-二-金" tabindex="-1">☱ 兑卦　二　金 <a class="header-anchor" href="#☱-兑卦-二-金" aria-label="Permalink to &quot;☱ 兑卦　二　金&quot;">​</a></h4><p>兑为金　泽水困　泽地萃　泽山咸<br> 水山蹇　地山谦　雷山小过　雷泽归妹</p><p><strong>天时</strong>：雨泽、新月、星。<br><strong>地理</strong>：泽、水际、缺池、废井、山崩破裂之地、其地为刚卤。<br><strong>人物</strong>：少女、妾、歌妓、伶人、译人、巫师。<br><strong>人事</strong>：喜悦、口、谗毁、谤说、饮食。<br><strong>身体</strong>：舌、口喉、肺、痰、涎。<br><strong>时序</strong>：秋八月、酉年月日时、二四九月日。<br><strong>静物</strong>：金刀、金类、乐器、废物、缺器。<br><strong>动物</strong>：羊、泽中之物。<br><strong>屋舍</strong>：西向之居、近泽之居、败墙壁宅、户有损。<br><strong>家宅</strong>：不安、防口舌、秋占喜悦、夏占家宅有祸。<br><strong>饮食</strong>：羊肉、泽中之物、宿味、辛辣之味。<br><strong>婚姻</strong>：不成、秋占可成、有喜、主成婚之吉、利婚少女、夏占不利。<br><strong>生产</strong>：不利、恐有损胎或则生女、夏占不利、宜坐向西。<br><strong>求名</strong>：难成、因名有损、利西之任、宜刑官、武职、伶官、译官。<br><strong>求利</strong>：无利、有损、财利、主口舌、秋占有财喜、夏占破财。<br><strong>出行</strong>：不宜远行、防口舌、或损失、宜西行、秋占宜行有利。<br><strong>交易</strong>：难利、防口舌、有争竞、夏占不利、秋占有交易之财。<br><strong>谋旺</strong>：难成、谋中有损、秋占有喜、夏占不遂。<br><strong>谒见</strong>：利行西方、见有咒诅。<br><strong>疾病</strong>：口舌、咽喉之疾、气逆喘疾、饮食不飧。<br><strong>坟墓</strong>：宜西向、防穴中有水、近泽之墓、夏占不宜、或葬废穴。<br><strong>官讼</strong>：争讼不已、曲直未决、因讼有损、防刑、秋占为体得理胜讼。<br><strong>姓字</strong>：商音、带口带金字旁姓氏、行位四二九。<br><strong>数目</strong>：四、二、九。<br><strong>方道</strong>：西方。<br><strong>五色</strong>：白。<br><strong>五味</strong>：辛、辣。</p><hr><blockquote><p>右万物之象，庶事之多不止于此。占者宜各以其类而推之耳。</p></blockquote><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>霰</td><td>xiàn</td><td>雪珠，空中水汽遇冷凝结成的小冰粒</td></tr><tr><td>公廨</td><td>gōng xiè</td><td>官署，官府办公之所</td></tr><tr><td>蕃鲜</td><td>fān xiān</td><td>茂盛鲜嫩</td></tr><tr><td>萑苇</td><td>huán wěi</td><td>芦苇类植物</td></tr><tr><td>风宪</td><td>fēng xiàn</td><td>监察官员，掌风纪法宪之职</td></tr><tr><td>肱</td><td>gōng</td><td>上臂，肩至肘之间</td></tr><tr><td>资贼</td><td>zī zéi</td><td>盗贼，此处指坎卦险陷之人</td></tr><tr><td>矫揉之物</td><td>jiǎo róu</td><td>经过弯曲加工的器物，如弓</td></tr><tr><td>痼冷</td><td>gù lěng</td><td>久治不愈的寒冷之症</td></tr><tr><td>干亢</td><td>gān kàng</td><td>干燥高亢之地</td></tr><tr><td>刚卤</td><td>gāng lǔ</td><td>坚硬盐碱之地</td></tr><tr><td>黔喙·黔啄</td><td>qián huì</td><td>黑嘴的动物，泛指鸟兽</td></tr><tr><td>山岚</td><td>shān lán</td><td>山中雾气</td></tr><tr><td>蓏</td><td>luǒ</td><td>草本植物的果实</td></tr><tr><td>阍寺</td><td>hūn sì</td><td>守门人</td></tr><tr><td>飧</td><td>sūn</td><td>熟食，此处「不飧」指饮食不消化</td></tr><tr><td>角音·征音·宫音·商音·羽音</td><td>—</td><td>五音，对应五行：角木·征火·宫土·商金·羽水</td></tr></tbody></table><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、两张表的关系" tabindex="-1">一、两张表的关系 <a class="header-anchor" href="#一、两张表的关系" aria-label="Permalink to &quot;一、两张表的关系&quot;">​</a></h3><p>本篇包含两张表，功能不同，互为补充：</p><table tabindex="0"><thead><tr><th></th><th>八卦类象（简表）</th><th>八卦万物属类（详表）</th></tr></thead><tbody><tr><td>性质</td><td>象的核心词，精炼</td><td>象的应用展开，详细</td></tr><tr><td>用途</td><td>起卦时快速取象</td><td>断卦时查询具体事项</td></tr><tr><td>与篇之二关系</td><td>精简版</td><td>详细版，两者互补</td></tr></tbody></table><p>篇之二的万物属类标注「并为上卦」，是<strong>起卦工具</strong>；<br> 篇之三的万物属类按天时·地理·人物·人事·身体·时序·动静物·屋舍·家宅·婚姻·饮食·生产·求名·谋旺·交易·求利·出行·谒见·疾病·官讼·坟墓·方道·五色·姓字·数目·五味二十余项展开，是<strong>断卦手册</strong>。</p><h3 id="二、每卦详表的内在结构" tabindex="-1">二、每卦详表的内在结构 <a class="header-anchor" href="#二、每卦详表的内在结构" aria-label="Permalink to &quot;二、每卦详表的内在结构&quot;">​</a></h3><p>每卦详表，隐含一个固定的判断逻辑：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当令（旺季）→ 诸事顺遂</span></span>
<span class="line"><span>被克（衰季）→ 诸事不利</span></span></code></pre></div><p>以乾卦为例：</p><ul><li>秋占（金旺）：宅兴隆·婚宜成·生贵子·求名利·大利·得胜</li><li>夏占（火克金）：有祸·不利·损财·失理·大凶</li></ul><p>这个逻辑贯穿八卦所有事项，是断卦时最基本的时令判断框架。</p><h3 id="三、五音配五行" tabindex="-1">三、五音配五行 <a class="header-anchor" href="#三、五音配五行" aria-label="Permalink to &quot;三、五音配五行&quot;">​</a></h3><p>详表中「姓字」一栏出现五音，对应关系如下：</p><table tabindex="0"><thead><tr><th>五音</th><th>五行</th><th>对应卦</th></tr></thead><tbody><tr><td>宫音</td><td>土</td><td>坤、艮</td></tr><tr><td>商音</td><td>金</td><td>乾、兑</td></tr><tr><td>角音</td><td>木</td><td>震、巽</td></tr><tr><td>征音</td><td>火</td><td>离</td></tr><tr><td>羽音</td><td>水</td><td>坎</td></tr></tbody></table><p>这是古代通过人的姓名声音来判断五行属性的方法，与字形取象（带金旁·带木旁·点水旁）并用。</p><h3 id="四、数目系统说明" tabindex="-1">四、数目系统说明 <a class="header-anchor" href="#四、数目系统说明" aria-label="Permalink to &quot;四、数目系统说明&quot;">​</a></h3><p>各卦数目来源混用了两套系统：</p><table tabindex="0"><thead><tr><th>卦</th><th>数目</th><th>来源</th></tr></thead><tbody><tr><td>乾</td><td>一·四·九</td><td>先天数(一)·河图数(四·九)</td></tr><tr><td>坤</td><td>八·五·十</td><td>先天数(八)·河图数(五·十)</td></tr><tr><td>震</td><td>四·八·三</td><td>先天数(四·八)·河图数(三)</td></tr><tr><td>巽</td><td>五·三·八</td><td>先天数(五)·河图数(三·八)</td></tr><tr><td>坎</td><td>一·六</td><td>河图生成数（天一生水·地六成之）</td></tr><tr><td>离</td><td>三·二·七</td><td>先天数(三)·河图数(二·七)</td></tr><tr><td>艮</td><td>五·七·十</td><td>先天数(七)·河图数(五·十)</td></tr><tr><td>兑</td><td>四·二·九</td><td>先天数(二)·河图数(四·九)</td></tr></tbody></table><p>这与❓-007·008相关，目前理解为：<strong>先天数是起卦用，河图数是断卦取期用</strong>，两套数字在不同场景下各有侧重。待卷三「观梅数诀序」进一步印证。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="同五行-不同象" tabindex="-1">同五行，不同象 <a class="header-anchor" href="#同五行-不同象" aria-label="Permalink to &quot;同五行，不同象&quot;">​</a></h3><p>这张表最值得停留的地方，是<strong>同五行的卦，象却截然不同</strong>：</p><p><strong>乾与兑，同属金：</strong><br> 乾是<strong>天上的金</strong>——圆满、刚健、运行不息，金最完整的状态。<br> 兑是<strong>泽边的金</strong>——有缺口、开口、喜悦，金被打开的状态。</p><blockquote><p>同是金，一个是完整的圆，一个是有缺的口。</p></blockquote><p><strong>震与巽，同属木：</strong><br> 震是<strong>雷中的木</strong>——突发、震动、一击而起，木向上冲的力量。<br> 巽是<strong>风中的木</strong>——渗透、顺入、无声而动，木向旁延伸的力量。</p><blockquote><p>同是木，一个是劈开，一个是渗进去。</p></blockquote><p><strong>坤与艮，同属土：</strong><br> 坤是<strong>平地的土</strong>——无边无际，承载一切，静默包容。<br> 艮是<strong>山上的土</strong>——突起耸立，阻隔边界，止而不动。</p><blockquote><p>同是土，一个是铺展，一个是耸立。</p></blockquote><p>断卦时，不能只看五行，要感受具体是哪个卦的象。</p><h3 id="身体是最直接的象" tabindex="-1">身体是最直接的象 <a class="header-anchor" href="#身体是最直接的象" aria-label="Permalink to &quot;身体是最直接的象&quot;">​</a></h3><p>八卦配身体，每一个都有内在道理：</p><ul><li>乾配<strong>首</strong>——天在最高处，头在最高处</li><li>坤配<strong>腹</strong>——地承载万物，腹承载脏腑</li><li>震配<strong>足</strong>——雷动则行，足是行动之本</li><li>巽配<strong>股</strong>——风渗透延伸，股是延伸之处</li><li>坎配<strong>耳·血</strong>——水流有声，耳听；血液流动如水</li><li>离配<strong>目</strong>——火是光明，目感知光明</li><li>艮配<strong>手·鼻·背</strong>——山是边界，手触边界；鼻如山之突起；背是阻断之象</li><li>兑配<strong>口·舌</strong>——泽有开口，口是人的开口</li></ul><p>身体就是一个小宇宙，八卦就在身上。感受到了，就不需要背。</p><h3 id="离卦的有壳之物" tabindex="-1">离卦的有壳之物 <a class="header-anchor" href="#离卦的有壳之物" aria-label="Permalink to &quot;离卦的有壳之物&quot;">​</a></h3><p>离中虚——外实中空。</p><p>看离卦的动物：雉·龟·鳖·蟹·螺·蚌——全是有壳的。<br> 壳是硬的（外刚），里面是软的（内空）。</p><p>这不是巧合，是象的一致性在说话。<br> 所有属离的东西，都有「外表光鲜文彩，内里空」的特质。<br> 文书有纹理，甲胄有纹饰，火焰最亮处中心是暗的——这是离的象。</p><h3 id="末句的提醒" tabindex="-1">末句的提醒 <a class="header-anchor" href="#末句的提醒" aria-label="Permalink to &quot;末句的提醒&quot;">​</a></h3><blockquote><p>右万物之象，庶事之多不止于此。占者宜各以其类而推之耳。</p></blockquote><p>邵雍在这里说得很清楚：<strong>这张表列不完，要自己去推类</strong>。</p><p>表是起点，不是终点。当你遇到表里没有的东西，要能感受它属于哪个卦的象，然后推类而断。这与「推数又须明理」是同一个原则——规则给范围，感悟给答案。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>八卦类象（简表）：起卦快速取象</li><li>八卦万物属类（详表）：断卦查询手册，按二十余项事类展开</li><li>当令则旺·被克则衰：贯穿所有事项的时令判断框架</li><li>同五行不同象：乾兑·震巽·坤艮，各有差异，感受比记忆重要</li><li>身体配卦：首乾·腹坤·足震·股巽·耳血坎·目离·手鼻背艮·口舌兑</li><li>五音配五行：角木·征火·宫土·商金·羽水</li></ul><p><strong>规律提炼</strong></p><ol><li>每卦所有象，都有一个<strong>内在一致的核心意象</strong>，感受到核心，就能推类</li><li>断卦时：先查详表找对应事项 → 再结合体用生克 → 再看时令旺衰 → 综合判断</li><li>表是工具，象是灵魂——「占者宜各以其类而推之」</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之二万物属类是「起卦用」，篇之三是「断卦用」，两张表配合使用</li><li>1-2节的八宫五行在这里得到完整展开</li><li>「推数又须明理」的原则，在末句「占者宜各以其类而推之」中再次印证</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-007 / <strong><strong>❓</strong></strong>-008</strong>（合并）：各卦数目混用了先天数与河图数两套系统，目前理解为先天数用于起卦，河图数用于断卦取期。待卷三「观梅数诀序」章节进一步印证。</p></blockquote>`,103)])])}const c=r(g,[["render",a]]);export{p as __pageData,c as default};
